package com.hms.website;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="website_content_items") public class WebsiteContentItem { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Enumerated(EnumType.STRING) @Column(nullable=false) private ContentCategory category; @Column(nullable=false,length=240) private String title; @Column(nullable=false,length=240) private String slug; @Column(length=500) private String summary; @Column(nullable=false,length=12000) private String body; @Column(length=500) private String imageUrl; @Enumerated(EnumType.STRING) @Column(nullable=false) private ContentStatus status; private OffsetDateTime publishedAt; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; protected WebsiteContentItem(){} public WebsiteContentItem(UUID tenantId,CreateContentRequest r){this.id=UUID.randomUUID();this.tenantId=tenantId;this.category=r.category();this.title=r.title().trim();this.slug=r.slug().trim().toLowerCase();this.summary=r.summary();this.body=r.body();this.imageUrl=r.imageUrl();this.status=r.status();this.publishedAt=r.status()==ContentStatus.PUBLISHED?OffsetDateTime.now():null;this.createdAt=OffsetDateTime.now();this.updatedAt=createdAt;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public ContentCategory getCategory(){return category;} public String getTitle(){return title;} public String getSlug(){return slug;} public String getSummary(){return summary;} public String getBody(){return body;} public String getImageUrl(){return imageUrl;} public ContentStatus getStatus(){return status;} public OffsetDateTime getPublishedAt(){return publishedAt;} }
